66	/// NVIDIA HPC SDK layouts; runtime loading (`LD_LIBRARY_PATH`, rpath) is out of scope.
67	pub struct CudaToolkit {
68	    pub root: PathBuf,
69	    /// `{root}/bin/nvcc` when present, otherwise bare `nvcc` from `$PATH`.
70	    pub nvcc: PathBuf,
71	    pub include_dirs: Vec<PathBuf>,
72	    lib_dirs: Vec<PathBuf>,
73	}
