75	impl CudaToolkit {
76	    pub fn discover() -> Self {
77	        println!("cargo:rerun-if-env-changed=CUDA_HOME");
78	        println!("cargo:rerun-if-env-changed=CUDA_PATH");
79	        let env_root = env::var("CUDA_HOME")
80	            .or_else(|_| env::var("CUDA_PATH"))
81	            .ok();
82	        if let Some(root) = env_root.as_deref().filter(|root| !Path::new(root).is_dir()) {
83	            println!(
84	                "cargo:warning=CUDA root {root} (from CUDA_HOME/CUDA_PATH) is not a directory"
85	            );
86	        }
87	        let root = env_root.map_or_else(|| PathBuf::from("/usr/local/cuda"), PathBuf::from);
88	        Self::from_root(root)
89	    }
