        panic!(
            "{var}={} has no readable manifest.txt: {err}",
            dir.display()
        )
    });
    println!(
        "cargo:warning=Using pre-generated {} TileLang CUDA from {}",
        family.label,
        dir.display()
    );
    println!("cargo:rerun-if-changed={}", manifest.display());
    Some(parse_tilelang_manifest(
        &text,
        &format!("{var} manifest.txt"),
        &dir,
    ))
}

