// dedupe-lab/src/main.rs —— 示例代码（复制自 pegainfer-build/src/lib.rs 并做展示性改造）
use std::path::{Path, PathBuf};

fn target_dirs() -> Vec<String> {
    let arch =
        std::env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_else(|_| std::env::consts::ARCH.to_string());
    match arch.as_str() {
        "aarch64" => vec!["aarch64-linux".to_string(), "sbsa-linux".to_string()],
        arch => vec![format!("{arch}-linux")],
    }
}

fn existing_deduped(dirs: Vec<PathBuf>) -> Vec<PathBuf> {
    let mut seen = Vec::new();
    let mut out = Vec::new();
    for dir in dirs {
        if !dir.is_dir() {
            continue;
        }
        let canon = dir.canonicalize().unwrap_or_else(|_| dir.clone());
        if !seen.contains(&canon) {
            seen.push(canon);
            out.push(dir);
        }
    }
    out
}

struct CudaToolkit {
    root: PathBuf,
    nvcc: PathBuf,
    include_dirs: Vec<PathBuf>,
    lib_dirs: Vec<PathBuf>, // 示例代码中改为 pub 以便观察
}

impl CudaToolkit {
    fn from_root(root: PathBuf) -> Self {
        let nvcc = root.join("bin/nvcc");
        let nvcc = if nvcc.is_file() { nvcc } else { PathBuf::from("nvcc") };
        let mut include_dirs = vec![root.join("include")];
        let mut lib_dirs = vec![root.join("lib64"), root.join("lib")];
        for target in target_dirs() {
            include_dirs.push(root.join(format!("targets/{target}/include")));
            lib_dirs.push(root.join(format!("targets/{target}/lib")));
        }
        Self { nvcc, include_dirs: existing_deduped(include_dirs), lib_dirs: existing_deduped(lib_dirs), root }
    }
    fn header_dir(&self, header: &str) -> Option<PathBuf> {
        self.include_dirs.iter().find(|dir| dir.join(header).is_file()).cloned()
    }
    fn link_search(&self) {
        if self.lib_dirs.is_empty() {
            println!("cargo:warning=no CUDA library dir found under {}", self.root.display());
        }
        for dir in &self.lib_dirs {
            println!("cargo:rustc-link-search=native={}", dir.display());
        }
    }
}

fn main() {
    // 1. 搭树：targets/<arch>/include/cuda.h + targets/<arch>/lib，再把根部的
    //    include、lib 做成指向它们的符号链接（复刻 symlinked_dirs_dedupe 测试）
    let tree = tempfile::tempdir().unwrap();
    let root = tree.path().to_path_buf();
    let target = target_dirs().remove(0);
    let inc_file = root.join(format!("targets/{target}/include/cuda.h"));
    std::fs::create_dir_all(inc_file.parent().unwrap()).unwrap();
    std::fs::write(&inc_file, b"").unwrap();
    std::fs::create_dir_all(root.join(format!("targets/{target}/lib"))).unwrap();
    std::os::unix::fs::symlink(root.join(format!("targets/{target}/include")), root.join("include")).unwrap();
    std::os::unix::fs::symlink(root.join(format!("targets/{target}/lib")), root.join("lib")).unwrap();

    // 2. 探测并断言：收敛后各只剩一项，header_dir 命中符号链接路径
    let tk = CudaToolkit::from_root(root.clone());
    assert_eq!(tk.include_dirs.len(), 1);
    assert_eq!(tk.lib_dirs.len(), 1);
    assert_eq!(tk.header_dir("cuda.h"), Some(root.join("include")));
